"""
Dependency node.

Classes:

- :class:`DependencyNode`: Dependency node with dependers and prerequisites.
"""

import weakref


class DependencyNode(object):
    """
    Dependency node with dependers and prerequisites.

    Dependers are other managed objects, which depend on this managed object.
    Prerequisites are other managed objects, which this managed object depends
    on.

    Methods:

    - :meth:`add_prerequisite`: add a prerequisite to this managed object

    Example usage:

        >>> from taf.internal.managedobject.dependency_node import DependencyNode
        >>> node = DependencyNode()
        >>> prerequisite1 = DependencyNode()
        >>> prerequisite2 = DependencyNode()
        >>> node.add_prerequisite(prerequisite1)
        >>> node.add_prerequisite(prerequisite2)
        >>> node.prerequisites == [prerequisite1, prerequisite2]
        True
        >>> set(prerequisite1.dependers) == set([node])
        True
        >>> type(prerequisite2.dependers)
        <class '_weakrefset.WeakSet'>
    """

    def __init__(self, **kwargs):
        """
        Create a dependency node.
        """
        super(DependencyNode, self).__init__(**kwargs)
        self.__dependers = weakref.WeakSet()
        self.__prerequisites = []

    def add_prerequisite(self, prerequisite):
        """
        Add a prerequisite to this managed object.

        :param ManagedObject prerequisite:
            a managed object, on which this managed object depends
        """

        self.__prerequisites.append(prerequisite)
        prerequisite.__dependers.add(self)

    @property
    def dependers(self):
        """
        Dependers of this managed object as WeakSet.
        """
        return self.__dependers

    @property
    def prerequisites(self):
        """
        Prerequisites of this managed object as a list.
        """

        return self.__prerequisites
